window.__OPENSTAX_PHYSICS__[21] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:33:30.884Z","number":21,"code":"ch21","slug":"the-quantum-nature-of-light","title":"The Quantum Nature of Light","titleVi":"Bản Chất Lượng Tử Của Ánh Sáng (Quantum Nature of Light)","sections":[{"uid":"hsphys.ch21.sec00","moduleId":"m54562","number":"21.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch21.sec00.sub01","title":"Chapter Introduction","summaryVi":null,"paragraphs":["At first glance, the quantum nature of light can be a strange and bewildering concept. Between light acting as discrete chunks, massless particles providing momenta, and fundamental particles behaving like waves, it may often seem like something out of Alice in Wonderland.","For many, the study of this branch of physics can be as enthralling as Lewis Carroll’s classic novel. Recalling the works of legendary characters and brilliant scientists such as Einstein, Planck, and Compton, the study of light’s quantum nature will provide you an interesting tale of how a clever interpretation of some small details led to the most important discoveries of the past 150 years. From the electronics revolution of the twentieth century to our future progress in solar energy and space exploration, the quantum nature of light should yield a rabbit hole of curious consequence, within which lie some of the most fascinating truths of our time."],"figures":[{"sourceId":"fs-id1167064848846","filename":"CNX_HSPhysics_21_00_Alice.jpg","relativePath":"media/CNX_HSPhysics_21_00_Alice.jpg","alt":"An image from the book Alice in Wonderland is shown. Alice is attending a tea party with the Mad Hatter and the White Rabbit."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch21.sec01","moduleId":"m54566","number":"21.1","slug":"planck-and-quantum-nature-of-light","title":"Planck and Quantum Nature of Light","isIntroduction":false,"learningObjectives":["Describe blackbody radiation","Define quantum states and their relationship to modern physics","Calculate the quantum energy of lights","Explain how photon energies vary across divisions of the electromagnetic spectrum"],"bilingualGuide":{"notebookSummaryVi":"Bức xạ vật đen, Khủng hoảng tử ngoại và Giả thuyết lượng tử năng lượng của Max Planck (E = nhf).","wordProblemCues":[{"phraseEn":"Planck’s constant h","meaningVi":"Hằng số Planck h = 6.63 × 10⁻³⁴ J·s","mathNotation":"E = hf"}],"commonTrapsVi":["Chú ý đơn vị năng lượng electron-volt: 1 eV = 1.60 × 10⁻¹⁹ J!"]},"keyEquations":[{"name":"quantum energy","formula":"\\(E = nhf\\)"}],"subsections":[{"uid":"hsphys.ch21.sec01.sub01","title":"Blackbodies","summaryVi":null,"paragraphs":["Our first story of curious significance begins with a T-shirt. You are likely aware that wearing a tight black T-shirt outside on a hot day provides a significantly less comfortable experience than wearing a white shirt. Black shirts, as well as all other black objects, will absorb and re-emit a significantly greater amount of radiation from the sun. This shirt is a good approximation of what is called a blackbody .","A perfect blackbody is one that absorbs and re-emits all radiated energy that is incident upon it. Imagine wearing a tight shirt that did this! This phenomenon is often modeled with quite a different scenario. Imagine carving a small hole in an oven that can be heated to very high temperatures. As the temperature of this container gets hotter and hotter, the radiation out of this dark hole would increase as well, re-emitting all energy provided it by the increased temperature. The hole may even begin to glow in different colors as the temperature is increased. Like a burner on your stove, the hole would glow red, then orange, then blue, as the temperature is increased. In time, the hole would continue to glow but the light would be invisible to our eyes. This container is a good model of a perfect blackbody.","It is the analysis of blackbodies that led to one of the most consequential discoveries of the twentieth century. Take a moment to carefully examine [Figure 21.1]. What relationships exist? What trends can you see? The more time you spend interpreting this figure, the closer you will be to understanding quantum physics!"],"figures":[{"sourceId":"fs-id1167063629171","filename":"CNX_HSPhysics_21_01_Blackbody-d846.jpg","relativePath":"media/CNX_HSPhysics_21_01_Blackbody-d846.jpg","alt":"A graph plotting radiation intensity against wavelength is shown. On the graph, there are three lines, each one corresponding to the temperature of a different radiator. Each of the three lines curves sharply upward and then gradually back downward. This shows two things: First, for each temperature, there is energy emitted across the electromagnetic section. Second, there is a peak wavelength, where the radiation intensity is greatest. On the graph it can be seen that as temperatures get hotter, the peak wavelength shifts to the left of the visible spectrum."}],"tables":[]},{"uid":"hsphys.ch21.sec01.sub02","title":"Understanding Blackbody Graphs","summaryVi":null,"paragraphs":["[Figure 21.1] is a plot of radiation intensity against radiated wavelength. In other words, it shows how the intensity of radiated light changes when a blackbody is heated to a particular temperature.","It may help to just follow the bottom-most red line labeled 3,000 K, red hot. The graph shows that when a blackbody acquires a temperature of 3,000 K, it radiates energy across the electromagnetic spectrum. However, the energy is most intensely emitted at a wavelength of approximately 1000 nm. This is in the infrared portion of the electromagnetic spectrum. While a body at this temperature would appear red-hot to our eyes, it would truly appear ‘infrared-hot’ if we were able to see the entire spectrum.","A few other important notes regarding [Figure 21.1]:","While in science it is important to categorize observations, theorizing as to why the observations exist is crucial to scientific advancement. Why doesn’t a blackbody emit radiation evenly across all wavelengths? Why does the temperature of the body change the peak wavelength that is radiated? Why does an increase in temperature cause the peak wavelength emitted to decrease? It is questions like these that drove significant research at the turn of the twentieth century. And within the context of these questions, Max Planck discovered something of tremendous importance."],"figures":[],"tables":[]},{"uid":"hsphys.ch21.sec01.sub03","title":"Planck’s Revolution","summaryVi":null,"paragraphs":["The prevailing theory at the time of Max Planck’s discovery was that intensity and frequency were related by the equation \\(I = \\frac{2kT}{{\\lambda}^{2}}.\\) This equation, derived from classical physics and using wave phenomena, infers that as wavelength increases, the intensity of energy provided will decrease with an inverse-squared relationship. This relationship is graphed in [Figure 21.1] and shows a troubling trend. For starters, it should be apparent that the graph from this equation does not match the blackbody graphs found experimentally. Additionally, it shows that for an object of any temperature, there should be an infinite amount of energy quickly emitted in the shortest wavelengths. When theory and experimental results clash, it is important to re-evaluate both models. The disconnect between theory and reality was termed the ultraviolet catastrophe .","Due to concerns over the ultraviolet catastrophe, Max Planck began to question whether another factor impacted the relationship between intensity and wavelength. This factor, he posited, should affect the probability that short wavelength light would be emitted. Should this factor reduce the probability of short wavelength light, it would cause the radiance curve to not progress infinitely as in the classical theory, but would instead cause the curve to precipitate back downward as is shown in the 5,000 K, 4,000 K, and 3,000 K temperature lines of the graph in [Figure 21.1]. Planck noted that this factor, whatever it may be, must also be dependent on temperature, as the intensity decreases at lower and lower wavelengths as the temperature increases.","The determination of this probability factor was a groundbreaking discovery in physics, yielding insight not just into light but also into energy and matter itself. It would be the basis for Planck’s 1918 Nobel Prize in Physics and would result in the transition of physics from classical to modern understanding. In an attempt to determine the cause of the probability factor, Max Planck constructed a new theory. This theory, which created the branch of physics called quantum mechanics , speculated that the energy radiated by the blackbody could exist only in specific numerical, or quantum , states. This theory is described by the equation \\(E = nhf,\\) where n is any nonnegative integer (0, 1, 2, 3, …) and h is Planck’s constant , given by \\(h = 6.626\\, \\times \\,{10}^{-34}\\text{J} \\cdot \\text{s},\\) and f is frequency.","Through this equation, Planck’s probability factor can be more clearly understood. Each frequency of light provides a specific quantized amount of energy. Low frequency light, associated with longer wavelengths would provide a smaller amount of energy, while high frequency light, associated with shorter wavelengths, would provide a larger amount of energy. For specified temperatures with specific total energies, it makes sense that more low frequency light would be radiated than high frequency light. To a degree, the relationship is like pouring coins through a funnel. More of the smaller pennies would be able to pass through the funnel than the larger quarters. In other words, because the value of the coin is somewhat related to the size of the coin, the probability of a quarter passing through the funnel is reduced!","Furthermore, an increase in temperature would signify the presence of higher energy. As a result, the greater amount of total blackbody energy would allow for more of the high frequency, short wavelength, energies to be radiated. This permits the peak of the blackbody curve to drift leftward as the temperature increases, as it does from the 3,000 K to 4,000 K to 5,000 K values. Furthering our coin analogy, consider a wider funnel. This funnel would permit more quarters to pass through and allow for a reduction in concern about the probability factor .","In summary, it is the interplay between the predicted classical model and the quantum probability that creates the curve depicted in [Figure 21.1]. Just as quarters have a higher currency denomination than pennies, higher frequencies come with larger amounts of energy. However, just as the probability of a quarter passing through a fixed diameter funnel is reduced, so is the probability of a high frequency light existing in a fixed temperature object. As is often the case in physics, it is the balancing of multiple incredible ideas that finally allows for better understanding."],"figures":[{"sourceId":"fs-id1167066885729","filename":"CNX_HSPhysics_21_01_Comparison.jpg","relativePath":"media/CNX_HSPhysics_21_01_Comparison.jpg","alt":"A graph plotting intensity of spectral radiation (or, loosely speaking, brightness) vs wavelength is shown. There is another line shown, called ‘Classical Theory.’ This line starts at the right of the graph and curves sharply upward and to the left. It appears to reach an infinite value around 1.2 micrometers."}],"tables":[]},{"uid":"hsphys.ch21.sec01.sub04","title":"Quantization","summaryVi":null,"paragraphs":["It may be helpful at this point to further consider the idea of quantum states. Atoms, molecules, and fundamental electron and proton charges are all examples of physical entities that are quantized —that is, they appear only in certain discrete values and do not have every conceivable value. On the macroscopic scale, this is not a revolutionary concept. A standing wave on a string allows only particular harmonics described by integers. Going up and down a hill using discrete stair steps causes your potential energy to take on discrete values as you move from step to step. Furthermore, we cannot have a fraction of an atom, or part of an electron’s charge, or 14.33 cents. Rather, everything is built of integral multiples of these substructures.","That said, to discover quantum states within a phenomenon that science had always considered continuous would certainly be surprising. When Max Planck was able to use quantization to correctly describe the experimentally known shape of the blackbody spectrum, it was the first indication that energy was quantized on a small scale as well. This discovery earned Planck the Nobel Prize in Physics in 1918 and was such a revolutionary departure from classical physics that Planck himself was reluctant to accept his own idea. The general acceptance of Planck’s energy quantization was greatly enhanced by Einstein’s explanation of the photoelectric effect (discussed in the next section), which took energy quantization a step further."],"figures":[{"sourceId":"fs-id1167063416308","filename":"CNX_HSPhysics_21_01_Planck.jpg","relativePath":"media/CNX_HSPhysics_21_01_Planck.jpg","alt":"A photo of Max Planck sitting at a desk is shown. The photo is taken from his side and he appears to be reading a document."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch21.sec01.ex01","number":"21.1.1","title":"How Many Photons per Second Does a Typical Light Bulb Produce?","problem":"Assuming that 10 percent of a 100-W light bulb’s energy output is in the visible range (typical for incandescent bulbs) with an average wavelength of 580 nm, calculate the number of visible photons emitted per second.","problemImages":[],"strategy":"The number of visible photons per second is directly related to the amount of energy emitted each second, also known as the bulb’s power. By determining the bulb’s power, the energy emitted each second can be found. Since the power is given in watts, which is joules per second, the energy will be in joules. By comparing this to the amount of energy associated with each photon, the number of photons emitted each second can be determined.","solution":"The power in visible light production is 10.0 percent of 100 W, or 10.0 J/s. The energy of the average visible photon is found by substituting the given average wavelength into the formula\n\\(E = nhf = \\frac{nhc}{\\lambda}.\\)\nBy rearranging the above formula to determine energy per photon, this produces\n\\(E/n = \\frac{(6.63\\, \\times \\,{10}^{- 34}\\text{J} \\cdot \\text{s})(3.00\\, \\times \\,{10}^{8}\\text{m}/\\text{s})}{580\\, \\times \\,{10}^{- 9}\\text{m}} = 3.43\\, \\times \\,{10}^{- 19}\\text{J}/\\text{p}\\text{h}\\text{o}\\text{t}\\text{o}\\text{n}.\\)\nThe number of visible photons per second is thus\n\\(\\frac{\\text{p}\\text{h}\\text{o}\\text{t}\\text{o}\\text{n}\\text{s}}{\\text{sec}} = \\frac{10.0\\text{J}/\\text{s}}{3.43\\, \\times \\,{10}^{- 19}\\text{J}/\\text{p}\\text{h}\\text{o}\\text{t}\\text{o}\\text{n}} = 2.92\\, \\times \\,{10}^{19}\\text{p}\\text{h}\\text{o}\\text{t}\\text{o}\\text{n}\\text{s}/\\text{s.}\\)","solutionImages":[],"solutionTables":[],"discussion":"This incredible number of photons per second is verification that individual photons are insignificant in ordinary human experience. However, it is also a verification of our everyday experience—on the macroscopic scale, photons are so small that quantization becomes essentially continuous."},{"uid":"hsphys.ch21.sec01.ex02","number":"21.1.2","title":"How does Photon Energy Change with Various Portions of the EM Spectrum?","problem":"Refer to the Graphs of Blackbody Radiation shown in the first figure in this section. Compare the energy necessary to radiate one photon of infrared light and one photon of visible light.","problemImages":[],"strategy":"To determine the energy radiated, it is necessary to use the equation \\(E = nhf.\\) It is also necessary to find a representative frequency for infrared light and visible light.","solution":"According to the first figure in this section, one representative wavelength for infrared light is 2000 nm (2.000 × 10 -6 m). The associated frequency of an infrared light is\n\\(f = \\frac{c}{\\lambda} = \\frac{3.00\\, \\times \\,{10}^{8}\\text{m}/\\text{s}}{2.000\\, \\times \\,{10}^{- 6}\\text{m}} = 1.50\\, \\times \\,{10}^{14}\\text{H}\\text{z}.\\)\nUsing the equation \\(E = nhf\\), the energy associated with one photon of representative infrared light is\n\\(\\frac{E}{n} = h \\cdot f = (6.63\\, \\times \\,{10}^{- 34}\\text{J} \\cdot \\text{s})(1.50\\, \\times \\,{10}^{14}\\text{Hz}) = 9.95\\, \\times \\,{10}^{- 20}\\frac{\\text{J}}{\\text{p}\\text{h}\\text{o}\\text{t}\\text{o}\\text{n}}.\\)\nThe same process above can be used to determine the energy associated with one photon of representative visible light. According to the first figure in this section, one representative wavelength for visible light is 500 nm.\n\\(f = \\frac{c}{\\lambda} = \\frac{3.00\\, \\times \\,{10}^{8}\\text{m}/\\text{s}}{5.00\\, \\times \\,{10}^{- 7}\\text{m}} = 6.00\\, \\times \\,{10}^{14}\\text{H}\\text{z}.\\)\n\\(\\frac{E}{n} = h \\cdot f = (6.63\\, \\times \\,{10}^{- 34}\\text{J} \\cdot \\text{s})(6.00\\, \\times \\,{10}^{14}\\text{Hz}) = 3.98\\, \\times \\,{10}^{- 19}\\frac{\\text{J}}{\\text{p}\\text{h}\\text{o}\\text{t}\\text{o}\\text{n}}.\\)","solutionImages":[],"solutionTables":[],"discussion":"This example verifies that as the wavelength of light decreases, the quantum energy increases. This explains why a fire burning with a blue flame is considered more dangerous than a fire with a red flame. Each photon of short-wavelength blue light emitted carries a greater amount of energy than a long-wavelength red light. This example also helps explain the differences in the 3,000 K, 4,000 K, and 6,000 K lines shown in the first figure in this section. As the temperature is increased, more energy is available for a greater number of short-wavelength photons to be emitted."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch21.sec01.feat01","type":"tip","title":"Tips for Success","text":"When encountering a new graph, it is best to try to interpret the graph before you read about it. Doing this will make the following text more meaningful and will help to remind yourself of some of the key concepts within the section.","images":[]}],"summaryPoints":["A blackbody will radiate energy across all wavelengths of the electromagnetic spectrum.","Radiation of a blackbody will peak at a particular wavelength, dependent on the temperature of the blackbody.","Analysis of blackbody radiation led to the field of quantum mechanics, which states that radiated energy can only exist in discrete quantum states."],"glossary":[{"term":"blackbody","termVi":"Vật đen tuyệt đối","definition":"object that absorbs all radiated energy that strikes it and also emits energy across all wavelengths of the electromagnetic spectrum","definitionVi":"Vật lý tưởng hấp thụ 100% mọi bức xạ chiếu tới nó và phát xạ nhiệt phụ thuộc duy nhất vào nhiệt độ.","memoryTipVi":"Bài toán mở đường cho sự ra đời của Thuyết lượng tử Planck (1900)."},{"term":"quantized","termVi":"Bị lượng tử hóa (Rời rạc từng bậc)","definition":"the fact that certain physical entities exist only with particular discrete values and not every conceivable value","definitionVi":"Chỉ nhận những giá trị gián đoạn từng gói nguyên lần, không biến thiên liên tục.","memoryTipVi":"Giống như đi bậc cầu thang (rời rạc) thay vì đi dốc trượt (liên tục)."},{"term":"quantum","termVi":"Lượng tử năng lượng (E = hf)","definition":"discrete packet or bundle of a physical entity such as energy","definitionVi":"Gói năng lượng nhỏ nhất mà sóng điện từ có thể phát ra hoặc hấp thụ: E = h·f (h = 6.626 × 10⁻³⁴ J·s).","memoryTipVi":"Số nhiều là Quanta."},{"term":"ultraviolet catastrophe","termVi":"Khủng hoảng tử ngoại","definition":"misconception that blackbodies would radiate high frequency energy at a much higher rate than energy radiated at lower frequencies","definitionVi":"Sự thất bại của Vật lý cổ điển khi dự đoán vật nóng phát ra năng lượng vô hạn ở vùng tử ngoại.","memoryTipVi":"Được Max Planck giải quyết bằng giả thuyết lượng tử năng lượng."}],"assessments":[{"uid":"hsphys.ch21.sec01.q001","sourceId":"fs-id1167067051003","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Do reflective or absorptive surfaces more closely model a perfect blackbody?","images":[],"choices":[{"label":"a","text":"reflective surfaces"},{"label":"b","text":"absorptive surfaces"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q004","sourceId":"fs-id1167067073001","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Why do we not notice quantization of photons in everyday experience?","images":[],"choices":[{"label":"a","text":"because the size of each photon is very large"},{"label":"b","text":"because the mass of each photon is so small"},{"label":"c","text":"because the energy provided by photons is very large"},{"label":"d","text":"because the energy provided by photons is very small"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q008","sourceId":"fs-id1167067090541","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"An AM radio station broadcasts at a frequency of 1,530 kHz . What is the energy in Joules of a photon emitted from this station?","images":[],"choices":[{"label":"a","text":"10.1 × 10 -26 J"},{"label":"b","text":"1.01 × 10 -28 J"},{"label":"c","text":"1.01 × 10 -29 J"},{"label":"d","text":"1.01 × 10 -27 J"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q009","sourceId":"fs-id1167066790192","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"A photon travels with energy of 1.0 eV. What type of EM radiation is this photon?","images":[],"choices":[{"label":"a","text":"visible radiation"},{"label":"b","text":"microwave radiation"},{"label":"c","text":"infrared radiation"},{"label":"d","text":"ultraviolet radiation"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q010","sourceId":"fs-id1167067033774","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What aspect of the blackbody spectrum forced Planck to propose quantization of energy levels in atoms and molecules?","images":[],"choices":[{"label":"a","text":"Radiation occurs at a particular frequency that does not change with the energy supplied."},{"label":"b","text":"Certain radiation occurs at a particular frequency that changes with the energy supplied."},{"label":"c","text":"Maximum radiation would occur at a particular frequency that does not change with the energy supplied."},{"label":"d","text":"Maximum radiation would occur at a particular frequency that changes with the energy supplied."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q011","sourceId":"fs-id1167067032970","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Two lasers shine red light at 650 nm. One laser is twice as bright as the other. Explain this difference using photons and photon energy.","images":[],"choices":[{"label":"a","text":"The brighter laser emits twice the number of photons and more energy per photon."},{"label":"b","text":"The brighter laser emits twice the number of photons and less energy per photon."},{"label":"c","text":"Both lasers emit equal numbers of photons and equivalent amounts of energy per photon."},{"label":"d","text":"The brighter laser emits twice the number of photons but both lasers emit equivalent amounts of energy per photon."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q012","sourceId":"fs-id1167067148112","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Consider four stars in the night sky: red, yellow, orange, and blue. The photons of which star will carry the greatest amount of energy?","images":[],"choices":[{"label":"a","text":"blue"},{"label":"b","text":"orange"},{"label":"c","text":"red"},{"label":"d","text":"yellow"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q013","sourceId":"eip-id1166848922431","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"A lightbulb is wired to a variable resistor. What will happen to the color spectrum emitted by the bulb as the resistance of the circuit is increased?","images":[],"choices":[{"label":"a","text":"The bulb will emit greener light."},{"label":"b","text":"The bulb will emit bluer light."},{"label":"c","text":"The bulb will emit more ultraviolet light."},{"label":"d","text":"The bulb will emit redder light."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q015","sourceId":"fs-id1167063539941","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Why does the intensity shown in the blackbody radiation graph decrease after its peak frequency is achieved?","images":[{"sourceId":"eip-idm321851360","filename":"CNX_HSPhysics_21_01_Blackbody-d846.jpg","relativePath":"media/CNX_HSPhysics_21_01_Blackbody-d846.jpg","alt":"A graph of blackbody radiation that shows curves of the intensity of E M radiation versus wavelength in nanometers."}],"choices":[{"label":"a","text":"Because after reaching the peak frequency, the photons created at a particular frequency are too many for energy intensity to continue to decrease."},{"label":"b","text":"Because after reaching the peak frequency, the photons created at a particular frequency are too few for energy intensity to continue to decrease."},{"label":"c","text":"Because after reaching the peak frequency, the photons created at a particular frequency are too many for energy intensity to continue to increase."},{"label":"d","text":"Because after reaching the peak frequency, the photons created at a particular frequency are too few for energy intensity to continue to increase."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q017","sourceId":"eip-id1166851316716","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Why is it assumed that a perfect absorber of light (like a blackbody) must also be a perfect emitter of light?","images":[],"choices":[{"label":"a","text":"To achieve electrostatic equilibrium with its surroundings"},{"label":"b","text":"To achieve thermal equilibrium with its surroundings"},{"label":"c","text":"To achieve mechanical equilibrium with its surroundings"},{"label":"d","text":"To achieve chemical equilibrium with its surroundings"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q018","sourceId":"fs-id1167067090541","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"An AM radio station broadcasts at a frequency of 1,530 kHz . What is the energy in Joules of a photon emitted from this station?","images":[],"choices":[{"label":"a","text":"10.1 × 10 -26 J"},{"label":"b","text":"1.01 × 10 -28 J"},{"label":"c","text":"1.01 × 10 -29 J"},{"label":"d","text":"1.01 × 10 -27 J"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q019","sourceId":"fs-id1167066790192","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A photon travels with energy of 1.0 eV. What type of EM radiation is this photon?","images":[],"choices":[{"label":"a","text":"visible radiation"},{"label":"b","text":"microwave radiation"},{"label":"c","text":"infrared radiation"},{"label":"d","text":"ultraviolet radiation"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q020","sourceId":"fs-id1167067166599","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"How many X-ray photons per second are created by an X-ray tube that produces a flux of X-rays having a power of\n1.00 W? Assume the average energy per photon is 75.0 keV.","images":[],"choices":[{"label":"a","text":"8.33 × 10 15 photons"},{"label":"b","text":"9.1 × 10 7 photons"},{"label":"c","text":"9.1 × 10 8 photons"},{"label":"d","text":"8.33 × 10 13 photons"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q021","sourceId":"fs-id1167067025238","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the frequency of a photon produced in a CRT using a 25.0-kV accelerating potential? This is similar to the layout as in older color television sets.","images":[],"choices":[{"label":"a","text":"6.04 × 10 -48 Hz"},{"label":"b","text":"2.77 × 10 -48 Hz"},{"label":"c","text":"3.02 × 10 18 Hz"},{"label":"d","text":"6.04 × 10 18 Hz"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q022","sourceId":"fs-id1167067034209","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A perfect blackbody is a perfect absorber of energy transferred by what method?","images":[],"choices":[{"label":"a","text":"conduction"},{"label":"b","text":"convection"},{"label":"c","text":"induction"},{"label":"d","text":"radiation"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q023","sourceId":"fs-id1167066829383","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which of the following is a physical entity that is quantized?","images":[],"choices":[{"label":"a","text":"electric charge of an ion"},{"label":"b","text":"frequency of a sound"},{"label":"c","text":"speed of a car"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q024","sourceId":"fs-id1167066952490","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Find the energy in joules of photons of radio waves that leave an FM station that has a 90.0-MHz broadcast frequency.","images":[],"choices":[{"label":"a","text":"1.8 × 10 -25 J"},{"label":"b","text":"1.11 × 10 -25 J"},{"label":"c","text":"7.1 × 10 -43 J"},{"label":"d","text":"5.96 × 10 -26 J"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q025","sourceId":"fs-id1167067184428","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which region of the electromagnetic spectrum will provide photons of the least energy?","images":[],"choices":[{"label":"a","text":"infrared light"},{"label":"b","text":"radio waves"},{"label":"c","text":"ultraviolet light"},{"label":"d","text":"X-rays"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q027","sourceId":"eip-id1166851025887","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Given two stars of equivalent size, which will have a greater temperature: a red dwarf or a yellow dwarf? Explain. Note—Our sun is considered a yellow dwarf.","images":[],"choices":[{"label":"a","text":"a yellow dwarf, because yellow light has lower frequency"},{"label":"b","text":"a red dwarf, because red light has lower frequency"},{"label":"c","text":"a red dwarf, because red light has higher frequency"},{"label":"d","text":"a yellow dwarf, because yellow light has higher frequency"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q029","sourceId":"fs-id1167067264246","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Because there are more gradations to high frequency radiation than low frequency radiation, scientists also thought it possible that a curve titled the ultraviolet catastrophe would occur. Explain what the blackbody radiation curve would look like if this were the case.","images":[],"choices":[{"label":"a","text":"The curve would steadily increase in intensity with increasing frequency."},{"label":"b","text":"The curve would steadily decrease in intensity with increasing frequency."},{"label":"c","text":"The curve would be much steeper than in the blackbody radiation graph."},{"label":"d","text":"The curve would be much flatter than in the blackbody radiation graph."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q030","sourceId":"fs-id1167067184448","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Energy provided by a light exists in the following quantities: 150 J, 225 J, 300 J. Define one possible quantum of energy and provide an energy state that cannot exist with this quantum.","images":[],"choices":[{"label":"a","text":"65 J; 450 J cannot exist"},{"label":"b","text":"70 J; 450 J cannot exist"},{"label":"c","text":"75 J; 375 J cannot exist"},{"label":"d","text":"75 J; 100 J cannot exist"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q032","sourceId":"fs-id1167066961090","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"How many 500-mm microwave photons are needed to supply the 8 kJ of energy necessary to heat a cup of water by 10 degrees Celsius?","images":[],"choices":[{"label":"a","text":"8.05 × 10 28 photons"},{"label":"b","text":"8.05 × 10 26 photons"},{"label":"c","text":"2.01 × 10 26 photons"},{"label":"d","text":"2.01 × 10 28 photons"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q033","sourceId":"fs-id1167067240435","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is the efficiency of a 100-W, 550-nm lightbulb if a photometer finds that 1 × 10 20 photons are emitted each second?","images":[],"choices":[{"label":"a","text":"101 percent"},{"label":"b","text":"72 percent"},{"label":"c","text":"18 percent"},{"label":"d","text":"36 percent"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q036","sourceId":"fs-id1167067041904","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Some television tubes are CRTs. They use an approximately 30-kV accelerating potential to send electrons to the screen, where the electrons stimulate phosphors to emit the light that forms the pictures we watch. Would you expect X-rays also to be created? Explain.","images":[],"choices":[{"label":"a","text":"No, because the full spectrum of EM radiation is not emitted at any temperature."},{"label":"b","text":"No, because the full spectrum of EM radiation is not emitted at certain temperatures."},{"label":"c","text":"Yes, because the full spectrum of EM radiation is emitted at any temperature."},{"label":"d","text":"Yes, because the full spectrum of EM radiation is emitted at certain temperatures."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec01.q038","sourceId":"fs-id1167063512630","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"What is the accelerating voltage of an X-ray tube that produces X-rays with the shortest wavelength of 0.0103 nm?","images":[],"choices":[{"label":"a","text":"1.21 × 10 10 V"},{"label":"b","text":"2.4 × 10 5 V"},{"label":"c","text":"3.0 × 10 -33 V"},{"label":"d","text":"1.21 × 10 5 V"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":4,"keyEquationCount":1,"subsectionCount":4,"workedExampleCount":2,"snapLabCount":0,"glossaryCount":4,"assessmentCount":25}},{"uid":"hsphys.ch21.sec02","moduleId":"m54559","number":"21.2","slug":"einstein-and-the-photoelectric-effect","title":"Einstein and the Photoelectric Effect","isIntroduction":false,"learningObjectives":["Describe Einstein’s explanation of the photoelectric effect","Describe how the photoelectric effect could not be explained by classical physics","Calculate the energy of a photoelectron under given conditions","Describe use of the photoelectric effect in biological applications, photoelectric devices and movie soundtracks"],"bilingualGuide":{"notebookSummaryVi":"Thuyết photon của Einstein và Hiện tượng quang điện (KE_max = hf - W₀): chỉ xảy ra khi tần số f ≥ tần số giới hạn f₀.","wordProblemCues":[{"phraseEn":"threshold frequency / work function","meaningVi":"Tần số giới hạn / Công thoát kim loại","mathNotation":"KE_max = hf - Φ"}],"commonTrapsVi":["Nếu tần số ánh sáng f < f₀ (bước sóng quá dài), dù tăng cường độ sáng mạnh đến mấy cũng KHÔNG bứt được electron nào!"]},"keyEquations":[{"name":"energy of a photon","formula":"\\(E = hf\\)"},{"name":"maximum kinetic energy of a photoelectron","formula":"\\(K{E}_{e} = hf - BE\\)"},{"name":"binding energy of an electron","formula":"\\(BE = h{f}_{O}\\)"}],"subsections":[{"uid":"hsphys.ch21.sec02.sub01","title":"The Photoelectric Effect","summaryVi":null,"paragraphs":["[EL]Ask the students what they think the term photoelectric means. How does the term relate to its definition?","When light strikes certain materials, it can eject electrons from them. This is called the photoelectric effect , meaning that light ( photo ) produces electricity. One common use of the photoelectric effect is in light meters, such as those that adjust the automatic iris in various types of cameras. Another use is in solar cells, as you probably have in your calculator or have seen on a rooftop or a roadside sign. These make use of the photoelectric effect to convert light into electricity for running different devices."],"figures":[{"sourceId":"fs-id1167065927016","filename":"CNX_HSPhysics_21_02_LightMeter.jpg","relativePath":"media/CNX_HSPhysics_21_02_LightMeter.jpg","alt":"A picture of a lightmeter is shown. There is a clear bulb placed on top of a black base. Inside the bulb is a metal plate attached to a wire. The wire drops into the black base and is no longer visible to the viewer."}],"tables":[]},{"uid":"hsphys.ch21.sec02.sub02","title":"Revolutionary Properties of the Photoelectric Effect","summaryVi":null,"paragraphs":["When Max Planck theorized that energy was quantized in a blackbody radiator, it is unlikely that he would have recognized just how revolutionary his idea was. Using tools similar to the light meter in [Figure 21.2], it would take a scientist of Albert Einstein ’s stature to fully discover the implications of Max Planck’s radical concept.","Through careful observations of the photoelectric effect, Albert Einstein realized that there were several characteristics that could be explained only if EM radiation is itself quantized . While these characteristics will be explained a bit later in this section, you can already begin to appreciate why Einstein’s idea is very important. It means that the apparently continuous stream of energy in an EM wave is actually not a continuous stream at all. In fact, the EM wave itself is actually composed of tiny quantum packets of energy called photons .","In equation form, Einstein found the energy of a photon or photoelectron to be","where E is the energy of a photon of frequency f and h is Planck’s constant. A beam from a flashlight, which to this point had been considered a wave, instead could now be viewed as a series of photons, each providing a specific amount of energy see [Figure 21.2]. Furthermore, the amount of energy within each individual photon is based upon its individual frequency, as dictated by \\(E = hf.\\) As a result, the total amount of energy provided by the beam could now be viewed as the sum of all frequency-dependent photon energies added together.","Just as with Planck’s blackbody radiation, Einstein’s concept of the photon could take hold in the scientific community only if it could succeed where classical physics failed. The photoelectric effect would be a key to demonstrating Einstein’s brilliance.","Consider the following five properties of the photoelectric effect. All of these properties are consistent with the idea that individual photons of EM radiation are absorbed by individual electrons in a material, with the electron gaining the photon’s energy. Some of these properties are inconsistent with the idea that EM radiation is a simple wave. For simplicity, let us consider what happens with monochromatic EM radiation in which all photons have the same energy hf .","where \\(K{E}_{e}\\) is the maximum kinetic energy of the ejected electron, \\(hf\\) is the photon’s energy, and BE is the binding energy of the electron to the particular material. The binding energy is also often called the work function of the material. This equation explains the properties of the photoelectric effect quantitatively and demonstrates that BE is the minimum amount of energy necessary to eject an electron. If the energy supplied is less than BE, the electron cannot be ejected. The binding energy can also be written as \\(BE = h{f}_{0},\\) where \\({f}_{0}\\) is the threshold frequency for the particular material. [Figure 21.2] shows a graph of maximum \\(K{E}_{e}\\) versus the frequency of incident EM radiation falling on a particular material.","In this demonstration , see how light knocks electrons off a metal target, and recreate the experiment that spawned the field of quantum mechanics.","In the circuit provided, what are the three ways to increase the current?"],"figures":[{"sourceId":"fs-id1167064848771","filename":"CNX_HSPhysics_21_02_Flashlight.jpg","relativePath":"media/CNX_HSPhysics_21_02_Flashlight.jpg","alt":"A drawing is shown of a flashlight with a beam projected out of it. Within the beam are a series of ovals that have wavelengths drawn within them. Each of these ovals corresponds to a photon. Near some of the photons is written the equation E = hf  while near other photons is written the equation E' = hf' . The symbols f and f' correspond to different frequencies (or colors) of light. The visible white light from the flashlight is a result of the combination of these different frequencies."},{"sourceId":"fs-id1167066086108","filename":"CNX_HSPhysics_21_02_PE-Effect.jpg","relativePath":"media/CNX_HSPhysics_21_02_PE-Effect.jpg","alt":"Four arrows representing ‘incoming radiation’ are shown striking a metal surface full of negative electrons. The metal surface is labeled ‘Sea of electrons inside the metal waiting to be set free.’ Leaving the metal surface are two new arrows, traveling upward and in the direction opposite the radiation strike. These arrows show the trajectory of two ejected electrons and are accompanied by the label ‘Electrons knocked out.’"},{"sourceId":"fs-id1167062547820","filename":"CNX_HSPhysics_21_02_Graph.jpg","relativePath":"media/CNX_HSPhysics_21_02_Graph.jpg","alt":"A graph shows the maximum kinetic energy of an electron plotted against the frequency of light. On the graph is a diagonal line, leaving the horizontal axis at a non-zero x-intercept labeled f0. The label f0 is accompanied with the equation f0 = BE/h. Also on the graph is the equation KEe = hf - BE. This equation explains the diagonal line, showing that as frequency increases, the electron's maximum kinetic energy does as well. However, this takes place only when the frequency is greater than f0, or BE/h."}],"tables":[]},{"uid":"hsphys.ch21.sec02.sub03","title":"Technological Applications of the Photoelectric Effect","summaryVi":null,"paragraphs":["While Einstein’s understanding of the photoelectric effect was a transformative discovery in the early 1900s, its presence is ubiquitous today. If you have watched streetlights turn on automatically in response to the setting sun, stopped elevator doors from closing simply by putting your hands between them, or turned on a water faucet by sliding your hands near it, you are familiar with the electric eye , a name given to a group of devices that use the photoelectric effect for detection.","All these devices rely on photoconductive cells. These cells are activated when light is absorbed by a semi-conductive material, knocking off a free electron. When this happens, an electron void is left behind, which attracts a nearby electron. The movement of this electron, and the resultant chain of electron movements, produces a current. If electron ejection continues, further holes are created, thereby increasing the electrical conductivity of the cell. This current can turn switches on and off and activate various familiar mechanisms.","One such mechanism takes place where you may not expect it. Next time you are at the movie theater, pay close attention to the sound coming out of the speakers. This sound is actually created using the photoelectric effect! The audiotape in the projector booth is a transparent piece of film of varying width. This film is fed between a photocell and a bright light produced by an exciter lamp. As the transparent portion of the film varies in width, the amount of light that strikes the photocell varies as well. As a result, the current in the photoconductive circuit changes with the width of the filmstrip. This changing current is converted to a changing frequency, which creates the soundtrack commonly heard in the theater.","What role does the photoelectric effect play in the research of a solar energy physicist?"],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch21.sec02.ex01","number":"21.2.1","title":"Photon Energy and the Photoelectric Effect: A Violet Light","problem":"(a) What is the energy in joules and electron volts of a photon of 420-nm violet light? (b) What is the maximum kinetic energy of electrons ejected from calcium by 420 nm violet light, given that the binding energy of electrons for calcium metal is 2.71 eV?","problemImages":[],"strategy":"To solve part (a), note that the energy of a photon is given by \\(E = hf\\) . For part (b), once the energy of the photon is calculated, it is a straightforward application of \\(K{E}_{e} = hf - BE\\) to find the ejected electron’s maximum kinetic energy, since BE is given.","solution":"Solution for (a)\nPhoton energy is given by\n\\(E = hf\\text{.}\\)\nSince we are given the wavelength rather than the frequency, we solve the familiar relationship \\(c = f\\lambda\\) for the frequency, yielding\n\\(f = \\frac{c}{\\lambda}\\) Combining these two equations gives the useful relationship\n\\(E = \\frac{hc}{\\lambda}.\\)\nNow substituting known values yields\n\\(E = \\frac{(6.63\\, \\times \\,{10}^{- 34}\\text{J} \\cdot \\text{s})(3.00\\, \\times \\,{10}^{8}m/s)}{4.20\\, \\times \\,{10}^{- 7}m} = 4.74\\, \\times \\,{10}^{-19}\\text{J}.\\)\nConverting to eV, the energy of the photon is\n\\(E = (4.74\\, \\times \\,{10}^{- 19}\\text{J} \\cdot \\text{s})\\frac{1\\,\\text{e}\\text{V}}{1.60\\, \\times \\,{10}^{- 19}\\text{J}} = 2.96\\,\\text{e}\\text{V}.\\)","solutionImages":[],"solutionTables":[],"discussion":"The energy of this 420 nm photon of violet light is a tiny fraction of a joule, and so it is no wonder that a single photon would be difficult for us to sense directly—humans are more attuned to energies on the order of joules. But looking at the energy in electron volts, we can see that this photon has enough energy to affect atoms and molecules. A DNA molecule can be broken with about 1 eV of energy, for example, and typical atomic and molecular energies are on the order of eV, so that the photon in this example could have biological effects, such as sunburn. The ejected electron has rather low energy, and it would not travel far, except in a vacuum. The electron would be stopped by a retarding potential of only 0.26 eV, a slightly larger KE than calculated above. In fact, if the photon wavelength were longer and its energy less than 2.71 eV, then the formula would give a negative kinetic energy, an impossibility. This simply means that the 420 nm photons with their 2.96 eV energy are not much above the frequency threshold. You can see for yourself that the threshold wavelength is 458 nm (blue light). This means that if calcium metal were used in a light meter, the meter would be insensitive to wavelengths longer than those of blue light. Such a light meter would be completely insensitive to red light, for example."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch21.sec02.feat01","type":"tip","title":"Table of Expected Results","text":"The following five pieces of information can be difficult to follow without some organization. It may be useful to create a table of expected results of each of the five properties, with one column showing the classical wave model result and one column showing the modern photon model result.\nThe table may look something like [Table_21_01]\nClassical Wave Model\nModern Photon Model\nThreshold Frequency\nElectron Ejection Delay\nIntensity of EM Radiation\nSpeed of Ejected Electrons\nRelationship between Kinetic Energy and Binding Energy","images":[]},{"uid":"hsphys.ch21.sec02.feat02","type":"physics-in-action","title":"Solar Energy Physicist","text":"According to the U.S. Department of Energy, Earth receives enough sunlight each hour to power the entire globe for a year. While converting all of this energy is impossible, the job of the solar energy physicist is to explore and improve upon solar energy conversion technologies so that we may harness more of this abundant resource.\nThe field of solar energy is not a new one. For over half a century, satellites and spacecraft have utilized photovoltaic cells to create current and power their operations. As time has gone on, scientists have worked to adapt this process so that it may be used in homes, businesses, and full-scale power stations using solar cells like the one shown in [Figure 21.2].\nA solar cell is an example of a photovoltaic cell. As light strikes the cell, the cell absorbs the energy of the photons. If this energy exceeds the binding energy of the electrons, then electrons will be forced to move in the cell, thereby producing a current. This current may be used for a variety of purposes. (credit: U.S. Department of Energy)\nSolar energy is converted to electrical energy in one of two manners: direct transfer through photovoltaic cells or thermal conversion through the use of a CSP, concentrating solar power, system. Unlike electric eyes, which trip a mechanism when current is lost, photovoltaic cells utilize semiconductors to directly transfer the electrons released through the photoelectric effect into a directed current. The energy from this current can then be converted for storage, or immediately used in an electric process. A CSP system is an indirect method of energy conversion. In this process, light from the Sun is channeled using parabolic mirrors. The light from these mirrors strikes a thermally conductive material, which then heats a pool of water. This water, in turn, is converted to steam, which turns a turbine and creates electricity. While indirect, this method has long been the traditional means of large-scale power generation.\nThere are, of course, limitations to the efficacy of solar power. Cloud cover, nightfall, and incident angle strike at high altitudes are all factors that directly influence the amount of light energy available. Additionally, the creation of photovoltaic cells requires rare-earth minerals that can be difficult to obtain. However, the major role of a solar energy physicist is to find ways to improve the efficiency of the solar energy conversion process. Currently, this is done by experimenting with new semi conductive materials, by refining current energy transfer methods, and by determining new ways of incorporating solar structures into the current power grid.\nAdditionally, many solar physicists are looking into ways to allow for increased solar use in impoverished, more remote locations. Because solar energy conversion does not require a connection to a large-scale power grid, research into thinner, more mobile materials will permit remote cultures to use solar cells to convert sunlight collected during the day into stored energy that can then be used at night.\nRegardless of the application, solar energy physicists are an important part of the future in responsible energy growth. While a doctoral degree is often necessary for advanced research applications, a bachelor's or master's degree in a related science or engineering field is typically enough to gain access into the industry. Computer skills are very important for energy modeling, including knowledge of CAD software for design purposes. In addition, the ability to collaborate and communicate with others is critical to becoming a solar energy physicist.","images":[{"sourceId":"fs-id1167063629171","filename":"CNX_HSPhysics_21_02_Photocell.jpg","relativePath":"media/CNX_HSPhysics_21_02_Photocell.jpg","alt":"There is an image of a blue solar cell. The solar cell is square, with diagonal notches removed from each corner."}]}],"summaryPoints":["The photoelectric effect is the process in which EM radiation ejects electrons from a material.","Einstein proposed photons to be quanta of EM radiation having energy \\(E = hf,\\) where f is the frequency of the radiation.","All EM radiation is composed of photons. As Einstein explained, all characteristics of the photoelectric effect are due to the interaction of individual photons with individual electrons.","The maximum kinetic energy KE e of ejected electrons (photoelectrons) is given by \\(K{E}_{e} = hf - BE,\\) where hf is the photon energy and BE is the binding energy (or work function) of the electron in the particular material."],"glossary":[{"term":"electric eye","termVi":"Mắt thần quang điện (Cảm biến quang)","definition":"group of devices that use the photoelectric effect for detection","definitionVi":"Thiết bị ứng dụng hiện tượng quang điện để tự động đóng mở cửa thang máy hoặc bật đèn.","memoryTipVi":"Ứng dụng thực tế của tế bào quang điện."},{"term":"photoelectric effect","termVi":"Hiện tượng quang điện ngoài","definition":"phenomenon whereby some materials eject electrons when exposed to light","definitionVi":"Hiện tượng ánh sáng có tần số đủ lớn chiếu vào mặt kim loại làm bật các electron ra ngoài.","memoryTipVi":"Công trình giúp Albert Einstein nhận giải Nobel Vật lý năm 1921!"},{"term":"photoelectron","termVi":"Quang êlectron","definition":"electron that has been ejected from a material by a photon of light","definitionVi":"Electron bị bứt ra khỏi bề mặt kim loại trong hiện tượng quang điện.","memoryTipVi":"KE_max = hf - Φ (Φ là công thoát kim loại)."},{"term":"photon","termVi":"Hạt Phôtôn (Lượng tử ánh sáng)","definition":"a quantum, or particle, of electromagnetic radiation","definitionVi":"Hạt ánh sáng không có khối lượng nghỉ, luôn bay với tốc độ c trong chân không và mang năng lượng E = hf = hc/λ.","memoryTipVi":"Bước sóng λ càng NGẮN → năng lượng photon càng LỚN!"}],"assessments":[{"uid":"hsphys.ch21.sec02.q002","sourceId":"fs-id1167065894866","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"True or false—Visible light is the only type of electromagnetic radiation that can cause the photoelectric effect.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q004","sourceId":"fs-id1167064832674","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Which aspects of the photoelectric effect can only be explained using photons?","images":[],"choices":[{"label":"a","text":"aspects 1, 2, and 3"},{"label":"b","text":"aspects 1, 2, and 4"},{"label":"c","text":"aspects 1, 2, 4 and 5"},{"label":"d","text":"aspects 1, 2, 3, 4 and 5"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q006","sourceId":"fs-id1167065972348","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"True or false—A current is created in a photoconductive cell, even if only one electron is expelled from a photon strike.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q008","sourceId":"fs-id1167065931476","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the longest-wavelength EM radiation that can eject a photoelectron from silver, given that the bonding energy is 4.73 eV ? Is this radiation in the visible range?","images":[],"choices":[{"label":"a","text":"2.63 × 10 -7 m; No, the radiation is in microwave region."},{"label":"b","text":"2.63 × 10 -7 m; No, the radiation is in visible region."},{"label":"c","text":"2.63 × 10 -7 m; No, the radiation is in infrared region."},{"label":"d","text":"2.63 × 10 -7 m; No, the radiation is in ultraviolet region."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q009","sourceId":"fs-id1167064541450","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the maximum kinetic energy in eV of electrons ejected from sodium metal by 450-nm EM radiation, given that the binding energy is 2.28 eV?","images":[],"choices":[{"label":"a","text":"0.48 V"},{"label":"b","text":"0.82 eV"},{"label":"c","text":"1.21 eV"},{"label":"d","text":"0.48 eV"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q011","sourceId":"fs-id1167062511479","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"True or false—The concept of a work function (or binding energy) is permissible under the classical wave model.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q012","sourceId":"fs-id1167065773202","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Can a single microwave photon cause cell damage?","images":[],"choices":[{"label":"a","text":"No, there is not enough energy associated with a single microwave photon to result in cell damage."},{"label":"b","text":"No, there is zero energy associated with a single microwave photon, so it does not result in cell damage."},{"label":"c","text":"Yes, a single microwave photon causes cell damage because it does not have high energy."},{"label":"d","text":"Yes, a single microwave photon causes cell damage because it has enough energy."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q013","sourceId":"fs-id1167064696692","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Light is projected onto a semi-conductive surface. If the intensity is held constant but the frequency of light is increased, what will happen?","images":[],"choices":[{"label":"a","text":"As frequency is increased, electrons will stop being ejected from the surface."},{"label":"b","text":"As frequency is increased, electrons will begin to be ejected from the surface."},{"label":"c","text":"As frequency is increased, it will have no effect on the electrons being ejected as the intensity is the same."},{"label":"d","text":"As frequency is increased, the rate at which the electrons are being ejected will increase."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q014","sourceId":"fs-id1167064910500","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Why is it important to consider what material to use when designing a light meter? Consider the worked example from Section 21-2 for assistance.","images":[],"choices":[{"label":"a","text":"A light meter should contain material that responds only to high frequency light."},{"label":"b","text":"A light meter should contain material that responds to low frequency light."},{"label":"c","text":"A light meter should contain material that has high binding energy."},{"label":"d","text":"A light meter should contain a material that does not show any photoelectric effect."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q015","sourceId":"fs-id1167062343028","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Why does overexposure to UV light often result in sunburn when overexposure to visible light does not? This is why you can get burnt even on a cloudy day.","images":[],"choices":[{"label":"a","text":"UV light carries less energy than visible light and can penetrate our body."},{"label":"b","text":"UV light carries more energy than visible light, so it cannot break bonds at the cellular level."},{"label":"c","text":"UV light carries more energy than visible light and can break bonds at the cellular level."},{"label":"d","text":"UV light carries less energy than visible light and cannot penetrate the human body."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q016","sourceId":"eip-id1166846437846","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"If you pick up and shake a piece of metal that has electrons in it free to move as a current, no electrons fall out. Yet if you heat the metal, electrons can be boiled off. Explain both of these facts as they relate to the amount and distribution of energy involved with shaking the object as compared with heating it.","images":[],"choices":[{"label":"a","text":"Thermal energy is added to the metal at a much higher rate than energy added due to shaking."},{"label":"b","text":"Thermal energy is added to the metal at a much lower rate than energy added due to shaking."},{"label":"c","text":"If the thermal energy added is below the binding energy of the electrons, they may be boiled off."},{"label":"d","text":"If the mechanical energy added is below the binding energy of the electrons, they may be boiled off."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q017","sourceId":"fs-id1167065931476","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the longest-wavelength EM radiation that can eject a photoelectron from silver, given that the bonding energy is 4.73 eV ? Is this radiation in the visible range?","images":[],"choices":[{"label":"a","text":"2.63 × 10 -7 m; No, the radiation is in microwave region."},{"label":"b","text":"2.63 × 10 -7 m; No, the radiation is in visible region."},{"label":"c","text":"2.63 × 10 -7 m; No, the radiation is in infrared region."},{"label":"d","text":"2.63 × 10 -7 m; No, the radiation is in ultraviolet region."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q018","sourceId":"fs-id1167064541450","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the maximum kinetic energy in eV of electrons ejected from sodium metal by 450-nm EM radiation, given that the binding energy is 2.28 eV?","images":[],"choices":[{"label":"a","text":"0.48 V"},{"label":"b","text":"0.82 eV"},{"label":"c","text":"1.21 eV"},{"label":"d","text":"0.48 eV"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q019","sourceId":"fs-id1167064638928","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the binding energy in eV of electrons in magnesium, if the longest-wavelength photon that can eject electrons is 337 nm?","images":[],"choices":[{"label":"a","text":"7.44 × 10 -19 J"},{"label":"b","text":"7.44 × 10 -49 J"},{"label":"c","text":"5.90 × 10 -17 J"},{"label":"d","text":"5.90 × 10 -19 J"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q020","sourceId":"fs-id1167065712964","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Photoelectrons from a material with a binding energy of 2.71 eV are ejected by 420-nm photons. Once ejected, how long does it take these electrons to travel 2.50 cm to a detection device?","images":[],"choices":[{"label":"a","text":"8.5 × 10 -6 s"},{"label":"b","text":"3.5 × 10 -7 s"},{"label":"c","text":"43.5 × 10 -9 s"},{"label":"d","text":"8.5 × 10 -8 s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q021","sourceId":"fs-id1167066137505","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is a quantum of light called?","images":[],"choices":[{"label":"a","text":"electron"},{"label":"b","text":"neutron"},{"label":"c","text":"photon"},{"label":"d","text":"proton"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q024","sourceId":"fs-id1167065967871","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which of the following terms translates to light-producing voltage ?","images":[],"choices":[{"label":"a","text":"photoelectric"},{"label":"b","text":"quantum mechanics"},{"label":"c","text":"photoconductive"},{"label":"d","text":"photovoltaic"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q027","sourceId":"fs-id1167062342436","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"According to wave theory, what is necessary to eject electrons from a surface?","images":[],"choices":[{"label":"a","text":"Enough energy to overcome the binding energy of the electrons at the surface"},{"label":"b","text":"A frequency that is higher than that of the electrons at the surface"},{"label":"c","text":"Energy that is lower than the binding energy of the electrons at the surface"},{"label":"d","text":"A very small number of photons"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q028","sourceId":"fs-id1167064766259","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is the wavelength of EM radiation that ejects 2.00-eV electrons from calcium metal, given that the binding energy is 2.71 eV?","images":[],"choices":[{"label":"a","text":"16.1 × 10 5 m"},{"label":"b","text":"6.21 × 10 -5 m"},{"label":"c","text":"9.94 × 10 -26 m"},{"label":"d","text":"2.63 × 10 -7 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q034","sourceId":"fs-id1167062373259","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A 500 nm photon of light strikes a semi-conductive surface with a binding energy of 2 eV. With what velocity will an electron be emitted from the semi-conductive surface?","images":[],"choices":[{"label":"a","text":"8.38 × 10 5 m/s"},{"label":"b","text":"9.33 × 10 5 m/s"},{"label":"c","text":"3 × 10 8 m/s"},{"label":"d","text":"4.11 × 10 5 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec02.q035","sourceId":"fs-id1167062939568","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"True or false—Treating food with ionizing radiation helps keep it from spoiling.","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":4,"keyEquationCount":3,"subsectionCount":3,"workedExampleCount":1,"snapLabCount":0,"glossaryCount":4,"assessmentCount":21}},{"uid":"hsphys.ch21.sec03","moduleId":"m54552","number":"21.3","slug":"the-dual-nature-of-light","title":"The Dual Nature of Light","isIntroduction":false,"learningObjectives":["Describe the Compton effect","Calculate the momentum of a photon","Explain how photon momentum is used in solar sails","Explain the particle-wave duality of light"],"bilingualGuide":{"notebookSummaryVi":"Động lượng photon (p = h/λ), Hiệu ứng Compton và Lưỡng tính sóng – hạt (bước sóng de Broglie λ = h/mv).","wordProblemCues":[{"phraseEn":"de Broglie wavelength","meaningVi":"Bước sóng vật chất của hạt vi mô","mathNotation":"λ = h / p"}],"commonTrapsVi":["Photon có khối lượng nghỉ m₀ = 0 nhưng VẪN CÓ động lượng p = h/λ ≠ 0!"]},"keyEquations":[{"name":"momentum of a photon (deBroglie relation)","formula":"\\(\\mathbf{p} = \\frac{h}{\\lambda}\\)"}],"subsections":[{"uid":"hsphys.ch21.sec03.sub01","title":"Photon Momentum","summaryVi":null,"paragraphs":["Do photons abide by the fundamental properties of physics? Can packets of electromagnetic energy possibly follow the same rules as a ping-pong ball or an electron? Although strange to consider, the answer to both questions is yes.","Despite the odd nature of photons, scientists prior to Einstein had long suspected that the fundamental particle of electromagnetic radiation shared properties with our more macroscopic particles. This is no clearer than when considering the photoelectric effect, where photons knock electrons out of a substance. While it is strange to think of a massless particle exhibiting momentum, it is now a well-established fact within the scientific community. [Figure 21.3] shows macroscopic evidence of photon momentum .","[Figure 21.3] shows a comet with two prominent tails. Comet tails are composed of gases and dust evaporated from the body of the comet and ionized gas. What most people do not know about the tails is that they always point away from the Sun rather than trailing behind the comet. This can be seen in the diagram.","Why would this be the case? The evidence indicates that the dust particles of the comet are forced away from the Sun when photons strike them. Evidently, photons carry momentum in the direction of their motion away from the Sun, and some of this momentum is transferred to dust particles in collisions. The blue tail is caused by the solar wind, a stream of plasma consisting primarily of protons and electrons evaporating from the corona of the Sun."],"figures":[{"sourceId":"fs-id1167063788791","filename":"CNX_HSPhysics_21_03_Comet.jpg","relativePath":"media/CNX_HSPhysics_21_03_Comet.jpg","alt":"There are two images shown. The left image is a drawing of a comet’s path around the sun. The comet’s path is shown with a black line, while the comet is drawn in orange for nine successive moments in time. In each comet drawing, the tail of the comet is seen pointing away from the sun. The right image is a photograph of a comet. In the image, the comet is seen with two tails: one bright white and one a faint blue."}],"tables":[]},{"uid":"hsphys.ch21.sec03.sub02","title":"Momentum, The Compton Effect, and Solar Sails","summaryVi":null,"paragraphs":["Momentum is conserved in quantum mechanics, just as it is in relativity and classical physics. Some of the earliest direct experimental evidence of this came from the scattering of X-ray photons by electrons in substances, a phenomenon discovered by American physicist Arthur H. Compton (1892–1962). Around 1923, Compton observed that X-rays reflecting from materials had decreased energy and correctly interpreted this as being due to the scattering of the X-ray photons by electrons. This phenomenon could be handled as a collision between two particles—a photon and an electron at rest in the material. After careful observation, it was found that both energy and momentum were conserved in the collision. See [Figure 21.3]. For the discovery of this conserved scattering, now known as the Compton effect , Arthur Compton was awarded the Nobel Prize in 1929.","Shortly after the discovery of Compton scattering, the value of the photon momentum, \\(\\mathbf{p} = \\frac{h}{\\lambda},\\)","was determined by Louis de Broglie. In this equation, called the de Broglie relation, h represents Planck’s constant and λ is the photon wavelength.","We can see that photon momentum is small, since \\(\\mathbf{p} = h/\\lambda .\\) and h is very small. It is for this reason that we do not ordinarily observe photon momentum. Our mirrors do not recoil when light reflects from them, except perhaps in cartoons. Compton saw the effects of photon momentum because he was observing X-rays, which have a small wavelength and a relatively large momentum, interacting with the lightest of particles, the electron."],"figures":[{"sourceId":"fs-id1167063506467","filename":"CNX_HSPhysics_21_03_Compton.jpg","relativePath":"media/CNX_HSPhysics_21_03_Compton.jpg","alt":"The image shows a collision between a photon of light and an electron. The photon of light is shown travelling downward and to the right toward a stationary electron, and then is shown rebounding upward and to the right after the drawn collision. The electron is shown stationary and the moving downward after the collision. Also in the image are the equations E = hf and E' = hf', which correspond to the energy of the photon before and after the collision. Near the electron is the equation KEe = E - E', showing the effect the collision has on the electron’s energy."}],"tables":[]},{"uid":"hsphys.ch21.sec03.sub03","title":"Section 21.3.3","summaryVi":null,"paragraphs":[],"figures":[{"sourceId":"fs-id1167067013076","filename":"CNX_HSPhysics_21_03_Cosmos1.jpg","relativePath":"media/CNX_HSPhysics_21_03_Cosmos1.jpg","alt":"There are two images shown. The image on the left is a drawing of a solar sail, which looks like a large parachute carrying a payload (the spacecraft). The solar sail is moving to the left. Blue arrows show photons from the sun moving from the right and striking the solar sail. The image on the right is an overhead photo of the very large solar sail unfurled. There are four people shown at the bottom of the picture for scale. They are approximately one-sixth of the width of the sail."}],"tables":[]},{"uid":"hsphys.ch21.sec03.sub04","title":"Particle-Wave Duality","summaryVi":null,"paragraphs":["We have long known that EM radiation is like a wave, capable of interference and diffraction. We now see that light can also be modeled as particles—massless photons of discrete energy and momentum. We call this twofold nature the particle-wave duality , meaning that EM radiation has properties of both particles and waves. This may seem contradictory, since we ordinarily deal with large objects that never act like both waves and particles. An ocean wave, for example, looks nothing like a grain of sand. However, this so-called duality is simply a term for properties of the photon analogous to phenomena we can observe directly, on a macroscopic scale. See [Figure 21.3]. If this term seems strange, it is because we do not ordinarily observe details on the quantum level directly, and our observations yield either particle-like or wave-like properties, but never both simultaneously.","Since we have a particle-wave duality for photons, and since we have seen connections between photons and matter in that both have momentum, it is reasonable to ask whether there is a particle-wave duality for matter as well. If the EM radiation we once thought to be a pure wave has particle properties, is it possible that matter has wave properties? The answer, strangely, is yes. The consequences of this are tremendous, as particle-wave duality has been a constant source of scientific wonder during the twentieth and twenty-first centuries."],"figures":[{"sourceId":"fs-id1167066766672","filename":"CNX_HSPhysics_21_03_Properties.jpg","relativePath":"media/CNX_HSPhysics_21_03_Properties.jpg","alt":"There are two drawings shown. On the left is a drawing of light striking a barrier with two slits. As the light passes through the slits, it creates an interference pattern. The interference pattern projects onto a screen, where the terms max and min are used to show the locations of constructive and destructive wave interference. On the right is an enlarged drawing of a grain of sand. There is an arrow pointing to the grain of sand, with a picture of a photon at the other end of the arrow."}],"tables":[]},{"uid":"hsphys.ch21.sec03.sub05","title":"Performance Task","summaryVi":null,"paragraphs":["Our scientific understanding of light has changed over time. There is evidence to support the wave model of light, just as there is evidence to support the particle model of light."],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch21.sec03.ex01","number":"21.3.1","title":"Electron and Photon Momentum Compared","problem":"(a) Calculate the momentum of a visible photon that has a wavelength of 500 nm. (b) Find the velocity of an electron having the same momentum. (c) What is the energy of the electron, and how does it compare with the energy of the photon?","problemImages":[],"strategy":"Finding the photon momentum is a straightforward application of its definition: \\(\\mathbf{p} = h/\\lambda .\\) If we find the photon momentum is small, we can assume that an electron with the same momentum will be nonrelativistic, making it easy to find its velocity and kinetic energy from the classical formulas.","solution":"Solution for (a)\nPhoton momentum is given by the de Broglie relation.\n\\(\\mathbf{p} = \\frac{h}{\\lambda}\\)\nEntering the given photon wavelength yields\n\\(\\mathbf{p} = \\frac{6.63\\, \\times \\,{10}^{-34}J \\cdot s}{5.00\\, \\times \\,{10}^{-7}\\text{m}} = 1.33\\, \\times \\,{10}^{-27}\\text{k}\\text{g} \\cdot \\text{m}/\\text{s}.\\)","solutionImages":[],"solutionTables":[],"discussion":"Even in huge numbers, the total momentum that photons carry is small. An electron that carries the same momentum as a 500-nm photon will have a 1,460 m/s velocity, which is clearly nonrelativistic. This is borne out by the experimental observation that it takes far less energy to give an electron the same momentum as a photon. That said, for high-energy photons interacting with small masses, photon momentum may be significant. Even on a large scale, photon momentum can have an effect if there are enough of them and if there is nothing to prevent the slow recoil of matter. Comet tails are one example, but there are also proposals to build space sails that use huge low-mass mirrors (made of aluminized Mylar) to reflect sunlight. In the vacuum of space, the mirrors would gradually recoil and could actually accelerate spacecraft within the solar system. See the following figure."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch21.sec03.feat01","type":"tip","title":"Tips for Success","text":"When determining energies in particle physics, it is more sensible to use the unit eV instead of Joules. Using eV will help you to recognize differences in magnitude more easily and will make calculations simpler. Also, eV is used by scientists to describe the binding energy of particles and their rest mass, so using eV will eliminate the need to convert energy quantities. Finally, eV is a convenient unit when linking electromagnetic forces to particle physics, as one eV is the amount energy given to an electron when placed in a field of 1-V potential difference.","images":[]},{"uid":"hsphys.ch21.sec03.feat02","type":"physics-in-action","title":"LightSail-1 Project","text":"“Provide ships or sails adapted to the heavenly breezes, and there will be some who will brave even that void.”\n— Johannes Kepler (in a letter to Galileo Galilei in 1608)\nNASA’s NanoSail-D, a precursor to LightSail-1, with its sails deployed. The Planetary Society will be launching LightSail-1 in early 2016. (credit: NASA/MSFC/D, Wikimedia Commons)\nTraversing the Solar System using nothing but the Sun’s power has long been a fantasy of scientists and science fiction writers alike. Though physicists like Compton, Einstein, and Planck all provided evidence of light’s propulsive capacity, it is only recently that the technology has become available to truly put these visions into motion. In 2016, by sending a lightweight satellite into space, the LightSail-1 project is designed to do just that.\nA citizen-funded project headed by the Planetary Society, the 5.45-million-dollar LightSail-1 project is set to launch two crafts into orbit around the Earth. Each craft is equipped with a 32-square-meter solar sail prepared to unfurl once a rocket has launched it to an appropriate altitude. The sails are made of large mirrors, each a quarter of the thickness of a trash bag, which will receive an impulse from the Sun’s reflecting photons. Each time the Sun’s photon strikes the craft’s reflective surface and bounces off, it will provide a momentum to the sail much greater than if the photon were simply absorbed.\nAttached to three tiny satellites called CubeSats, whose combined volume is no larger than a loaf of bread, the received momentum from the Sun’s photons should be enough to record a substantial increase in orbital speed. The intent of the LightSail-1 mission is to prove that the technology behind photon momentum travel is sound and can be done cheaply. A test flight in May 2015 showed that the craft’s Mylar sails could unfurl on command. With another successful result in 2016, the Planetary Society will be planning future versions of the craft with the hopes of eventually achieving interplanetary satellite travel. Though a few centuries premature, Kepler’s fantastic vision may not be that far away.","images":[{"sourceId":"fs-id1167067174714","filename":"CNX_HSPhysics_21_03_NanoSail.jpg","relativePath":"media/CNX_HSPhysics_21_03_NanoSail.jpg","alt":"An image of the NanoSail is shown. The sail is shown fully unfurled, with the satellite in the center. The width of the satellite is approximately one-eighth the width of the sail."}]}],"summaryPoints":["Compton scattering provided evidence that photon-electron interactions abide by the principles of conservation of momentum and conservation of energy.","The momentum of individual photons, quantified by \\(\\mathbf{p} = \\frac{h}{\\lambda}\\), can be used to explain observations of comets and may lead to future space technologies.","Electromagnetic waves and matter have both wave-like and particle-like properties. This phenomenon is defined as particle-wave duality."],"glossary":[{"term":"Compton effect","termVi":"Hiệu ứng tán xạ Compton","definition":"phenomenon whereby X-rays scattered from materials have decreased energy","definitionVi":"Hiện tượng tia X va chạm với electron như hai viên bi-a làm bước sóng tia X dài ra — chứng minh photon có ĐỘNG LƯỢNG!","memoryTipVi":"Khẳng định tính chất hạt của bức xạ điện từ."},{"term":"particle-wave duality","termVi":"Lưỡng tính sóng – hạt","definition":"property of behaving like either a particle or a wave; the term for the phenomenon that all particles have wave-like characteristics and waves have particle-like characteristics","definitionVi":"Bản chất kép của cả ánh sáng lẫn vật chất vi mô (electron): vừa thể hiện tính sóng (giao thoa, nhiễu xạ) vừa thể hiện tính hạt (quang điện, tán xạ).","memoryTipVi":"Bước sóng de Broglie của hạt: λ = h / p."},{"term":"photon momentum","termVi":"Động lượng của photon (p = h/λ)","definition":"amount of momentum of a photon, calculated by \\(\\mathbf{p} = \\frac{h}{\\lambda}\\)","definitionVi":"Dù không có khối lượng nghỉ, photon vẫn có động lượng p = E/c = h/λ.","memoryTipVi":"Cơ sở của cánh buồm mặt trời (Solar Sail) đẩy tàu vũ trụ bằng ánh sáng!"}],"assessments":[{"uid":"hsphys.ch21.sec03.q001","sourceId":"fs-id1167067236259","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What fundamental physics properties were found to be conserved in Compton scattering?","images":[],"choices":[{"label":"a","text":"energy and wavelength"},{"label":"b","text":"energy and momentum"},{"label":"c","text":"mass and energy"},{"label":"d","text":"energy and angle"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q002","sourceId":"fs-id1167066773756","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Why do classical or relativistic momentum equations not work in explaining the conservation of momentum that occurs in Compton scattering?","images":[],"choices":[{"label":"a","text":"because neither classical nor relativistic momentum equations utilize mass as a variable in their equations"},{"label":"b","text":"because relativistic momentum equations utilize mass as a variable in their formulas but classical momentum equations do not"},{"label":"c","text":"because classical momentum equations utilize mass as a variable in their formulas but relativistic momentum equations do not"},{"label":"d","text":"because both classical and relativistic momentum equations utilize mass as a variable in their formulas"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q004","sourceId":"fs-id1167066957443","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"True or false—It is possible to propel a solar sail craft using just particles within the solar wind.","images":[],"choices":[{"label":"a","text":"true"},{"label":"b","text":"false"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q005","sourceId":"fs-id1167067188995","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"True or false—Photon momentum more directly supports the wave model of light.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q006","sourceId":"fs-id1167063890068","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"True or false—wave-particle duality exists for objects on the macroscopic scale.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q007","sourceId":"eip-id1166849843729","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What type of electromagnetic radiation was used in Compton scattering?","images":[],"choices":[{"label":"a","text":"visible light"},{"label":"b","text":"ultraviolet radiation"},{"label":"c","text":"radio waves"},{"label":"d","text":"X-rays"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q008","sourceId":"fs-id1167067106637","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"Find the momentum of a 4.00-cm wavelength microwave photon.","images":[],"choices":[{"label":"a","text":"0.83 × 10 -32 kg ⋅ m/s"},{"label":"b","text":"1.66 × 10 -34 kg ⋅ m/s"},{"label":"c","text":"0.83 × 10 -34 kg ⋅ m/s"},{"label":"d","text":"1.66 × 10 -32 kg ⋅ m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q009","sourceId":"fs-id1167067140420","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"Calculate the wavelength of a photon that has the same momentum of a proton moving at 1.00 percent of the speed of light.","images":[],"choices":[{"label":"a","text":"2.43 × 10 -10 m"},{"label":"b","text":"2.43 × 10 -12 m"},{"label":"c","text":"1.32 × 10 -15 m"},{"label":"d","text":"1.32 × 10 -13 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q010","sourceId":"fs-id1167067070395","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Why don’t we feel the momentum of sunlight when we are on the beach?","images":[],"choices":[{"label":"a","text":"The momentum of a singular photon is incredibly small."},{"label":"b","text":"The momentum is not felt because very few photons strike us at any time, and not all have momentum."},{"label":"c","text":"The momentum of a singular photon is large, but very few photons strike us at any time."},{"label":"d","text":"A large number of photons strike us at any time, and so their combined momentum is incredibly large."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q013","sourceId":"fs-id1167067111832","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"In what region of the electromagnetic spectrum will photons be most effective in accelerating a solar sail?","images":[],"choices":[{"label":"a","text":"ultraviolet rays"},{"label":"b","text":"infrared rays"},{"label":"c","text":"X-rays"},{"label":"d","text":"gamma rays"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q014","sourceId":"fs-id1167066793604","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"True or false—Electron microscopes can resolve images that are smaller than the images resolved by light microscopes.","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q016","sourceId":"fs-id1167067106637","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Find the momentum of a 4.00-cm wavelength microwave photon.","images":[],"choices":[{"label":"a","text":"0.83 × 10 -32 kg ⋅ m/s"},{"label":"b","text":"1.66 × 10 -34 kg ⋅ m/s"},{"label":"c","text":"0.83 × 10 -34 kg ⋅ m/s"},{"label":"d","text":"1.66 × 10 -32 kg ⋅ m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q017","sourceId":"fs-id1167067140420","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Calculate the wavelength of a photon that has the same momentum of a proton moving at 1.00 percent of the speed of light.","images":[],"choices":[{"label":"a","text":"2.43 × 10 -10 m"},{"label":"b","text":"2.43 × 10 -12 m"},{"label":"c","text":"1.32 × 10 -15 m"},{"label":"d","text":"1.32 × 10 -13 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q018","sourceId":"fs-id1167066953803","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the momentum of a 0.0100-nm-wavelength photon that could detect details of an atom?","images":[],"choices":[{"label":"a","text":"6.626 × 10 -27 kg ⋅ m/s"},{"label":"b","text":"6.626 × 10 -32 kg ⋅ m/s"},{"label":"c","text":"6.626 × 10 -34 kg ⋅ m/s"},{"label":"d","text":"6.626 × 10 -23 kg ⋅ m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q019","sourceId":"fs-id1167063891968","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"The momentum of light is exactly reversed when reflected straight back from a mirror, assuming negligible recoil of the mirror. Thus the change in momentum is twice the initial photon momentum. Suppose light of intensity 1.00 kW/m2 reflectsfrom a mirror of area 2.00 m2 each second. Using the most general form of Newton’s second law, what is the force on the mirror?","images":[],"choices":[{"label":"a","text":"1.33 × 10 -5 N"},{"label":"b","text":"1.33 × 10 -6 N"},{"label":"c","text":"1.33 × 10 -7 N"},{"label":"d","text":"1.33 × 10 -8 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q020","sourceId":"fs-id1167063525010","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What two particles interact in Compton scattering?","images":[],"choices":[{"label":"a","text":"photon and electron"},{"label":"b","text":"proton and electron"},{"label":"c","text":"neutron and electron"},{"label":"d","text":"proton and neutron"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q021","sourceId":"fs-id1167067138634","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the momentum of a 500-nm photon?","images":[],"choices":[{"label":"a","text":"8.35 × 10 -26 kg ⋅ m/s"},{"label":"b","text":"3.31 × 10 -40 kg ⋅ m/s"},{"label":"c","text":"7.55 × 10 26 kg ⋅ m/s"},{"label":"d","text":"1.33 × 10 -27 kg ⋅ m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q022","sourceId":"fs-id1167067051272","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"The conservation of what fundamental physics principle is behind the technology of solar sails?","images":[],"choices":[{"label":"a","text":"charge"},{"label":"b","text":"mass"},{"label":"c","text":"momentum"},{"label":"d","text":"angular momentum"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q023","sourceId":"fs-id1167066820393","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Terms like frequency, amplitude, and period are tied to what component of wave-particle duality?","images":[],"choices":[{"label":"a","text":"neither the particle nor the wave model of light"},{"label":"b","text":"both the particle and wave models of light"},{"label":"c","text":"the particle model of light"},{"label":"d","text":"the wave model of light"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q024","sourceId":"eip-id1166851319896","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Why was it beneficial for Compton to scatter electrons using X-rays and not another region of light like microwaves?","images":[],"choices":[{"label":"a","text":"because X-rays are more penetrating than microwaves"},{"label":"b","text":"because X-rays have lower frequency than microwaves"},{"label":"c","text":"because microwaves have shorter wavelengths than X-rays"},{"label":"d","text":"because X-rays have shorter wavelength than microwaves"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q027","sourceId":"fs-id1167066832594","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A 500-nm photon strikes an electron and loses 20 percent of its energy. What is the new momentum of the photon?","images":[],"choices":[{"label":"a","text":"4.24 × 10 -27 kg ⋅ m/s"},{"label":"b","text":"3.18 × 10 -27 kg ⋅ m/s"},{"label":"c","text":"2.12 × 10 -27 kg ⋅ m/s"},{"label":"d","text":"1.06 × 10 -27 kg ⋅ m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q028","sourceId":"fs-id1167067069602","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A 500-nm photon strikes an electron and loses 20 percent of its energy. What is the speed of the recoiling electron?","images":[],"choices":[{"label":"a","text":"7.18 × 10 5 m/s"},{"label":"b","text":"6.18 × 10 5 m/s"},{"label":"c","text":"5.18 × 10 5 m/s"},{"label":"d","text":"4.18 × 10 5 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q029","sourceId":"fs-id1167063855574","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"When a photon strikes a solar sail, what is the direction of impulse on the photon?","images":[],"choices":[{"label":"a","text":"parallel to the sail"},{"label":"b","text":"perpendicular to the sail"},{"label":"c","text":"tangential to the sail"},{"label":"d","text":"opposite to the sail"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q031","sourceId":"fs-id1167067058275","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"The wavelength of a particle is called the de Broglie wavelength, and it can be found with the equation \\(p = \\frac{h}{\\lambda}\\) .\nYes or no—Can the wavelength of an electron match that of a proton?","images":[],"choices":[{"label":"a","text":"Yes, a slow-moving electron can achieve the same momentum as a slow-moving proton."},{"label":"b","text":"No, a fast-moving electron cannot achieve the same momentum, and hence the same wavelength, as a proton."},{"label":"c","text":"No, an electron can achieve the same momentum, and hence not the same wavelength, as a proton."},{"label":"d","text":"Yes, a fast-moving electron can achieve the same momentum, and hence have the same wavelength, as a slow-moving proton."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q034","sourceId":"fs-id1167066845643","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Sunlight above the Earth’s atmosphere has an intensity of 1.30 kW/m2 . If this is reflected straight back from a mirror that has only a small recoil, the light’s momentum is exactly reversed, giving the mirror twice the incident momentum. If the mirror were attached to a solar sail craft, how fast would the craft be moving after 24 hr? Note—The average mass per square meter of the craft is 0.100 kg.","images":[],"choices":[{"label":"a","text":"8.67 × 10 -5 m/s 2"},{"label":"b","text":"8.67 × 10 -6 m/s 2"},{"label":"c","text":"94.2 m/s"},{"label":"d","text":"7.49 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch21.sec03.q035","sourceId":"fs-id1167063588569","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Consider the counter-clockwise motion of LightSail-1 around Earth. When will the satellite move the fastest?","images":[{"sourceId":"fs-id1164562112849","filename":"CNX_HSPhysics_21_03_LightSail_img.jpg","relativePath":"media/CNX_HSPhysics_21_03_LightSail_img.jpg","alt":"The image shows Earth labeled on four sides with the sun to the right, with three arrows pointing in the direction of Earth. Point A is on the top. Point B is on the left, farthest from the sun. Point C is on the bottom. Point D is on the right, closest to the sun."}],"choices":[{"label":"a","text":"point A"},{"label":"b","text":"point B"},{"label":"c","text":"point C"},{"label":"d","text":"point D"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":4,"keyEquationCount":1,"subsectionCount":5,"workedExampleCount":1,"snapLabCount":0,"glossaryCount":3,"assessmentCount":26}}],"summary":{"totalSections":4,"totalKeyEquations":5,"totalWorkedExamples":4,"totalSnapLabs":0,"totalGlossaryTerms":11,"totalAssessments":72,"referencedMediaCount":15},"qualityGate":{"passed":true,"checkedUids":93,"errors":[],"warnings":[]}};
